import{z as l,x as s,o as n,c as p,q as t,j as o,D as E,d as A,s as B,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"契约条款","description":"","frontmatter":{"title":"契约条款","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/covenants.md","filePath":"econ/covenants.md","lastUpdated":1791063341000}'),d={name:"econ/covenants.md"};function D(c,a,m,C,F,h){const r=s("Mermaid");return n(),p("div",null,[a[2]||(a[2]=t('<h1 id="契约条款" tabindex="-1">契约条款 <a class="header-anchor" href="#契约条款" aria-label="Permalink to &quot;契约条款&quot;">​</a></h1><div class="epigraph"><p>债券契约把资产替代、稀释、股利掏空写成可验证的禁止项；它用状态依存的限制去替代把所有债务都做成短债。</p><footer>—— Smith and Warner, On Financial Contracting: An Analysis of Bond Covenants, Journal of Financial Economics 1979</footer></div><p><a href="/econ/debt-maturity-rollover">上一课</a>用到期日做检查。本课缺口是合同文本：Smith–Warner（1979）把条款分类为投资、融资、股利限制，用来降低代理成本，同时承认条款有灵活性成本。不重写展期危机的扩散模型，不把破产法提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/risk-shifting">风险转移</a>与积压来自优先级。短债用再定价来约束，但流动性代价高。条款用会计门槛（利息覆盖、杠杆上限）、资产出售限制、负向质押、股利限制，在长债内存入检查。缺口是：哪些扭曲可写成可验证条款，哪些只能靠控制权转移（违约）。Tirole：可验证的用契约，不可验证的用权威——与<a href="/econ/control-rights">控制权</a>同一不完全合同分工。</p><p><span class="marginnote">术语翻译：「负向质押」指承诺不再把资产抵押给新债主，保住老债人的优先地位；「利息覆盖倍数」是 EBIT 除以利息费用——EBIT 500 万、利息 250 万就是 2 倍，条款常要求它不低于某个数。</span></p><p><span class="marginnote">松弛（slack）：企业与门槛的距离。松弛耗尽触发技术性违约，即使清偿力尚在。条款把「违约」从无力偿债提前到比率违规，是故意的早期检查。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Smith–Warner 的清单：限制兼并与资产出售（防资产替代与担保稀释）；限制优先债与抵押（防索赔稀释）；限制股利与回购（防掏空）。收益：债值上升、股权的代理成本下降，事前 \\(V\\) 可以升。成本：正 NPV 的重组、投资、派息被拦下——灵活性像卖掉实物期权。</p><p>松紧与价格：紧条款降低票息，但提高技术性违约与再谈判频率。动态权衡：条款是调整带之外的另一套边界。评级机构把条款包进评级，后课再写。</p><p><span class="marginnote">数字实例：杠杆上限条款写「总债务 ÷ EBITDA ≤ 4」。企业债务 8 亿、EBITDA 2.5 亿，比率 3.2，尚有松弛；若 EBITDA 跌到 1.9 亿，比率冲到 4.2——即便付息现金流无忧，也已经构成技术性违约。</span></p>',11)),(n(),o(i,null,{default:E(()=>[B(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AG%5B%22%E8%B5%84%E4%BA%A7%E6%9B%BF%E4%BB%A3%20%2F%20%E7%A8%80%E9%87%8A%20%2F%20%E6%8E%8F%E7%A9%BA%22%5D%20--%3E%20COV%5B%22%E5%8F%AF%E9%AA%8C%E8%AF%81%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20COV%20--%3E%20GAIN%5B%22%E5%80%BA%E5%80%BC%E4%B8%8A%E5%8D%87%2C%20%E4%BA%8B%E5%89%8D%20V%22%5D%0A%20%20COV%20--%3E%20FLEX%5B%22%E7%81%B5%E6%B4%BB%E6%80%A7%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SHORT%5B%22%E7%9F%AD%E5%80%BA%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20ALT%5B%22%E6%9B%BF%E4%BB%A3%E6%88%96%E4%BA%92%E8%A1%A5%22%5D%0A%20%20COV%20--%3E%20CHK%5B%22%E6%AF%94%E7%8E%87%E9%97%A8%E6%A7%9B%20%3D%20%E6%97%A9%E6%9C%9F%E8%BF%9D%E7%BA%A6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"资本预算：项目可能撞上已有条款（capex 限制、杠杆测试）。NPV 要含再谈判或豁免的成本，不是只算经营 FCFF。这是 APV 的契约副作用。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是把不可定价的道德风险改写成可验证的约束。条款越完整，越接近把企业变成「按合同经营」——灵活性损失正是实物期权价值。再谈判使条款不是硬约束：违约后可以豁免，于是条款的纪律取决于债权人协调（后课）与是否有银行牵头。",-1)),(n(),o(i,null,{default:E(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%7B%22%E6%AF%94%E7%8E%87%E8%BF%98%E5%AE%88%E5%9C%A8%E9%97%A8%E6%A7%9B%E5%86%85%E5%90%97%3F%22%7D%20--%3E%7C%E6%98%AF%7C%20OK%5B%22%E7%BB%A7%E7%BB%AD%E6%8C%89%E5%90%88%E5%90%8C%E4%BB%98%E6%81%AF%E8%BF%98%E6%9C%AC%22%5D%0A%20%20T%20--%3E%7C%E5%90%A6%EF%BC%9A%E6%9D%BE%E5%BC%9B%E8%80%97%E5%B0%BD%7C%20TD%5B%22%E6%8A%80%E6%9C%AF%E6%80%A7%E8%BF%9D%E7%BA%A6%E8%A7%A6%E5%8F%91%22%5D%0A%20%20TD%20--%3E%20Q%7B%22%E5%80%BA%E6%9D%83%E4%BA%BA%E8%83%BD%E5%90%A6%E5%8D%8F%E8%B0%83%3F%22%7D%0A%20%20Q%20--%3E%7C%E8%B1%81%E5%85%8D%20%2F%20%E5%86%8D%E8%B0%88%E5%88%A4%7C%20W%5B%22%E6%9D%A1%E6%AC%BE%E9%87%8D%E8%AE%BE%E3%80%81%E7%A5%A8%E6%81%AF%E4%B8%8A%E8%B0%83%22%5D%0A%20%20Q%20--%3E%7C%E5%A4%B1%E8%B4%A5%20%2F%20%E5%90%84%E8%87%AA%E6%8A%A2%E8%B7%91%7C%20BC%5B%22%E6%8E%A7%E5%88%B6%E6%9D%83%E8%BD%AC%E7%A7%BB%EF%BC%9A%E8%BF%9B%E5%85%A5%E7%A0%B4%E4%BA%A7%E7%A8%8B%E5%BA%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">直觉类比：条款像仪表盘上的油量警示灯——灯亮不代表车已抛锚（清偿力还在），但强制你进厂检修（再谈判）。把检查提前，正是为了在发动机真正损坏之前抓住问题。</span></p><p>与 Jensen 债务纪律：还本是硬现金吐出；条款是行为限制。成熟 FCF 企业可能同时要两者；成长企业紧条款会加重积压。样本仍要匹配。</p><h3 id="条款不是免费的状态依存债" tabindex="-1">条款不是免费的状态依存债 <a class="header-anchor" href="#条款不是免费的状态依存债" aria-label="Permalink to &quot;条款不是免费的状态依存债&quot;">​</a></h3><p>把所有或有都写成条款，合同会不可执行或过度触发。最优是不完备：留下违约后的破产/重整来处理残差。这正是下一单元治理与第 11 章的接口，本课只在合同设计上点名。</p><p><span class="marginnote">Brealey–Myers：条款保护债权人，最终也保护股东——因为事前降低债务成本。事后股东会感觉被条款绑住，这是同一合同的两面，不是矛盾。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成信托契约的法律注释。对象是代理成本与灵活性。下一课银行债对公开债：谁持有条款、谁能监督与豁免，决定条款的实际硬度。</p><p>后课默认：条款用可验证限制替代部分短债检查；代价是实物期权。项目 NPV 必须读已有契约。技术性违约 ≠ 经济破产。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条款针对投资、融资、股利三类代理，用可验证门槛做早期检查。</li><li>收益是事前债值；成本是灵活性与再谈判。</li><li>与短债互补或替代；硬度取决于谁监督、能否协调豁免。</li><li>出处：Smith and Warner, <em>JFE</em> 1979；Tirole, <em>Theory of Corporate Finance</em>。</li></ul>',10))])}const u=l(d,[["render",D]]);export{T as __pageData,u as default};
